/*
 * test_core.c
 *
 * Host tests for the portable core: utilities, HTML/JSON reading, the WPSD
 * parsers and request builders, and the row layout. Reads sample replies
 * generated by mock_wpsd.py --dump-fixtures from the directory in argv[1].
 *
 * Built with ASan/UBSan (see the Makefile), so a parser overrun is a test
 * failure rather than something Rob finds on the RISC OS machine.
 */

#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "client.h"
#include "html.h"
#include "scan.h"
#include "json.h"
#include "rows.h"
#include "util.h"
#include "wpsd.h"

static int failures;
static int checks;

static void check_at(const char *file, int line, int ok, const char *expr)
{
    checks++;
    if (!ok) {
        failures++;
        printf("FAIL %s:%d: %s\n", file, line, expr);
    }
}

#define CHECK(c) check_at(__FILE__, __LINE__, (c), #c)

static void check_str_at(const char *file, int line, const char *got,
                         const char *want, const char *expr)
{
    checks++;
    if (strcmp(got, want) != 0) {
        failures++;
        printf("FAIL %s:%d: %s\n   got:  \"%s\"\n   want: \"%s\"\n", file,
               line, expr, got, want);
    }
}

#define CHECK_STR(got, want) check_str_at(__FILE__, __LINE__, (got), (want), #got)

static const char *fixture_dir;

static char *load(const char *name, size_t *len)
{
    char path[512];
    FILE *f;
    char *buf;
    long n;

    snprintf(path, sizeof path, "%s/%s", fixture_dir, name);
    f = fopen(path, "rb");
    if (f == NULL) {
        printf("FAIL cannot open fixture %s\n", path);
        failures++;
        *len = 0;
        return NULL;
    }

    fseek(f, 0, SEEK_END);
    n = ftell(f);
    fseek(f, 0, SEEK_SET);
    buf = (char *)malloc((size_t)n + 1);
    if (fread(buf, 1, (size_t)n, f) != (size_t)n) {
        printf("FAIL short read of %s\n", path);
        failures++;
    }
    buf[n] = '\0';
    fclose(f);
    *len = (size_t)n;
    return buf;
}

