static void test_util(void)
{
    char out[64];
    sbuf b;
    char s[40];

    CHECK(b64_encode((const unsigned char *)"", 0, out, sizeof out) == 0);
    CHECK(b64_encode((const unsigned char *)"f", 1, out, sizeof out) == 4);
    CHECK_STR(out, "Zg==");
    b64_encode((const unsigned char *)"fo", 2, out, sizeof out);
    CHECK_STR(out, "Zm8=");
    b64_encode((const unsigned char *)"foo", 3, out, sizeof out);
    CHECK_STR(out, "Zm9v");
    b64_encode((const unsigned char *)"pi-star:raspberry", 17, out, sizeof out);
    CHECK_STR(out, "cGktc3RhcjpyYXNwYmVycnk=");
    CHECK(b64_encode((const unsigned char *)"foobar", 6, out, 8) == 0);

    url_encode("Add & Link", out, sizeof out);
    CHECK_STR(out, "Add+%26+Link");
    url_encode("a-b_c.d~e", out, sizeof out);
    CHECK_STR(out, "a-b_c.d~e");
    url_encode("91,\n92", out, sizeof out);
    CHECK_STR(out, "91%2C%0A92");
    CHECK(url_encode("0123456789", out, 5) == (size_t)-1);
    CHECK(url_encode("%%%", out, 6) == (size_t)-1);

    CHECK(u_ieq("DMR", "dmr"));
    CHECK(!u_ieq("DMR", "dmrx"));
    CHECK(u_istarts("Content-Length: 5", "content-length:"));
    CHECK(u_find("hello world", 11, "o w") != NULL);
    CHECK(u_find("hello", 3, "llo") == NULL);       /* respects the length */
    CHECK(u_ifind("Hello", 5, "ELL") != NULL);

    strcpy(s, "  \t x y \r\n");
    u_trim(s);
    CHECK_STR(s, "x y");

    CHECK(u_copy(s, 4, "abcdef") == 3);
    CHECK_STR(s, "abc");

    sb_init(&b, 10);
    CHECK(sb_add(&b, "12345", 5) == 0);
    CHECK(sb_add(&b, "6789012345", 10) == 1);      /* truncated at 10 */
    CHECK(b.len == 10);
    CHECK(b.truncated);
    CHECK_STR(sb_str(&b), "1234567890");
    sb_free(&b);
    CHECK_STR(sb_str(&b), "");

    strcpy(s, "caf\xC3\xA9 \xE2\x80\x93 \xE2\x82\xAC \xF0\x9F\x98\x80 ok");
    utf8_to_latin1(s);
    CHECK_STR(s, "caf\xE9 - E ? ok");

    strcpy(s, "already \xE9 latin1");     /* lone 0xE9 stays */
    utf8_to_latin1(s);
    CHECK_STR(s, "already \xE9 latin1");

    strcpy(s, "trunc \xE2\x82");           /* cut mid-sequence */
    utf8_to_latin1(s);
    CHECK(strncmp(s, "trunc ", 6) == 0);
}

static void test_display_text(void)
{
    char t[80];

    /* New lines, tabs and other control characters become one space: the
     * desktop ends text at the first byte below 32. */
    u_copy(t, sizeof t, "Stopping\nStarting\t\tWPSD\r\nservices");
    utf8_to_latin1(t);
    CHECK_STR(t, "Stopping Starting WPSD services");

    u_copy(t, sizeof t, "a\001b\177c");
    utf8_to_latin1(t);
    CHECK_STR(t, "a b c");

    /* Colour codes are dropped, not shown as junk. */
    u_copy(t, sizeof t, "\033[32mdone\033[0m");
    utf8_to_latin1(t);
    CHECK_STR(t, "done");
    u_copy(t, sizeof t, "x\033[1;31;40my\033");     /* a lone ESC is a control character */
    utf8_to_latin1(t);
    CHECK_STR(t, "xy ");
    u_copy(t, sizeof t, "unterminated \033[12");
    utf8_to_latin1(t);
    CHECK_STR(t, "unterminated ");

    /* UTF-8 still comes out as Latin-1. */
    u_copy(t, sizeof t, "\xC2\xA9 Acorn \xE2\x80\x94 ok");
    utf8_to_latin1(t);
    CHECK_STR(t, "\xA9 Acorn - ok");

    u_copy(t, sizeof t, "line one\ntwo\x01\x1f three\x7f");
    u_no_ctrl(t);
    CHECK_STR(t, "line one two   three ");
}

static void test_scan_prefix(void)
{
    char out[24];

    CHECK(scan_prefix_from("10.0.0.27", out, sizeof out) && strcmp(out, "10.0.0.") == 0);
    CHECK(scan_prefix_from("10.0.0", out, sizeof out) && strcmp(out, "10.0.0.") == 0);
    CHECK(scan_prefix_from("10.0.0.", out, sizeof out) && strcmp(out, "10.0.0.") == 0);
    CHECK(scan_prefix_from("  192.168.1.254  ", out, sizeof out) &&
          strcmp(out, "192.168.1.") == 0);
    CHECK(scan_prefix_from("127.0.0.1\n", out, sizeof out) && strcmp(out, "127.0.0.") == 0);
    CHECK(!scan_prefix_from("", out, sizeof out));
    CHECK(!scan_prefix_from("10.0", out, sizeof out));
    CHECK(!scan_prefix_from("10", out, sizeof out));
    CHECK(!scan_prefix_from("10.0.0.1.5", out, sizeof out));
    CHECK(!scan_prefix_from("10.0.256.1", out, sizeof out));
    CHECK(!scan_prefix_from("10.0..1", out, sizeof out));
    CHECK(!scan_prefix_from("wpsd.local", out, sizeof out));
    CHECK(!scan_prefix_from("10.0.0.1x", out, sizeof out));
    CHECK(!scan_prefix_from("1000.0.0.1", out, sizeof out));
    CHECK(scan_new("nonsense", 80) == NULL);
}

static void test_html(void)
{
    char out[128];
    const char *h;
    const char *te;
    const char *d;
    const char *close;
    int v;

    h = "<span>M1ABC&nbsp B</span>";
    html_text(h, strlen(h), out, sizeof out);
    CHECK_STR(out, "M1ABC B");

    h = "<p>a  &amp;  b &lt;c&gt; &#39;q&#x27; &deg;C&nbsp;&bull;x</p>";
    html_text(h, strlen(h), out, sizeof out);
    CHECK_STR(out, "a & b <c> 'q' \xB0" "C *x");

    h = "x<!-- hidden <b>stuff</b> -->y<script>var a='<b>';</script>z"
        "<style>.a{}</style>w";
    html_text(h, strlen(h), out, sizeof out);
    CHECK_STR(out, "xyzw");

    h = "a<br />b</div>c&unknown;d & e";
    html_text(h, strlen(h), out, sizeof out);
    CHECK_STR(out, "a b c&unknown;d & e");

    html_text("abcdefghij", 10, out, 5);
    CHECK_STR(out, "abcd");

    /* Line-structured text keeps block boundaries as newlines. */
    h = "<div class=\"a\"> Mode  Status </div><div><span>DMR</span> <span>on</span></div>"
        "<br />third<p>fourth&nbsp;line</p>\n\n<div></div><div>last</div>";
    html_lines(h, strlen(h), out, sizeof out);
    CHECK_STR(out, "Mode Status\nDMR on\nthird\nfourth line\nlast");
    html_lines("</div></div>  x", 15, out, sizeof out);
    CHECK_STR(out, "x");
    html_lines("<td>a</td><td>b</td>", 20, out, sizeof out);
    CHECK_STR(out, "a b");

    /* Nested divs: the matching close, not the first one. */
    h = "<div id=a>x<div>y</div><div>z<div>w</div></div>t</div>after";
    d = html_find_tag(h, h + strlen(h), "div", &te);
    CHECK(d == h);
    close = html_div_close(te, h + strlen(h));
    CHECK(close != NULL && strncmp(close, "</div>after", 11) == 0);

    h = "<div class='x'><div class=\"status-pill active\" data-n=\"42\">t</div></div>";
    d = html_find_div(h, h + strlen(h), "status-pill", &te);
    CHECK(d != NULL);
    CHECK(html_attr_int(d, te, "data-n", &v) && v == 42);
    CHECK(!html_attr_int(d, te, "data-q", &v));
    {
        char val[16];

        CHECK(html_attr_str(d, te, "data-n", val, sizeof val) && strcmp(val, "42") == 0);
        CHECK(!html_attr_str(d, te, "data-q", val, sizeof val));
        CHECK(!html_attr_str(d, te, "data-n", val, 2));       /* did not fit */
    }

    /* Truncated input must not run off the end. */
    h = "<div class=\"abc";
    CHECK(html_find_tag(h, h + strlen(h), "div", &te) == NULL);
    CHECK(html_div_close(h, h + strlen(h)) == NULL);
}

static void test_json(void)
{
    const char *t1 = "[{\"a\":\"x\\/y\",\"b\":\"caf\\u00e9\",\"n\":12,\"t\":true,"
                     "\"z\":null,\"o\":{\"k\":[1,2,3]}}, {\"a\":\"\"}]";
    jnode *r = json_parse(t1, strlen(t1));
    const jnode *o;
    char tmp[16];

    CHECK(r != NULL && r->t == J_ARR && json_count(r) == 2);
    o = json_at(r, 0);
    CHECK_STR(json_string(o, "a", "?"), "x/y");
    u_copy(tmp, sizeof tmp, json_string(o, "b", "?"));
    utf8_to_latin1(tmp);
    CHECK_STR(tmp, "caf\xE9");
    CHECK(json_int(o, "n", -1) == 12);
    CHECK(json_int(o, "t", -1) == 1);
    CHECK(json_int(o, "missing", 7) == 7);
    CHECK_STR(json_string(o, "n", "dflt"), "dflt");     /* not a string */
    CHECK(json_count(json_member(json_member(o, "o"), "k")) == 3);
    CHECK_STR(json_string(json_at(r, 1), "a", "?"), "");
    json_free(r);

    /* Surrogate pair. */
    r = json_parse("\"\\ud83d\\ude00\"", 14);
    CHECK(r != NULL && r->t == J_STR && strlen(r->s) == 4);
    json_free(r);

    /* Errors. */
    CHECK(json_parse("[1,2", 4) == NULL);
    CHECK(json_parse("{\"a\":}", 6) == NULL);
    CHECK(json_parse("[1] x", 5) == NULL);
    CHECK(json_parse("", 0) == NULL);
    CHECK(json_parse("\"abc", 4) == NULL);
    CHECK(json_parse("\"a\\q\"", 5) == NULL);

    {
        char deep[200];
        int i;

        for (i = 0; i < 100; i++)
            deep[i] = '[';
        for (i = 0; i < 100; i++)
            deep[100 + i] = ']';
        CHECK(json_parse(deep, 200) == NULL);      /* nesting limit */
    }
}

